import{_ as e}from"./chunks/a05-job-overview.C-FIcYp3.js";import{_ as o,o as r,c as n,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const a="/rakkii-cars-guide/screenshots/v2/a01-login.png",d="/rakkii-cars-guide/screenshots/v2/a03-hub-switcher.png",i="/rakkii-cars-guide/screenshots/v2/a19-search.png",y=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"start/getting-started.md","filePath":"start/getting-started.md","lastUpdated":1794621279000}'),h={name:"start/getting-started.md"};function g(l,t,p,c,u,m){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Read this once. It takes about five minutes and covers what every role needs.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><ol><li>Open Rakkii Ops in a browser on your phone, tablet or computer.</li><li>Enter your <strong>Email</strong> and <strong>Password</strong> and press <strong>Sign in</strong>.</li><li>The app opens your home page:</li></ol><table tabindex="0"><thead><tr><th>Your role</th><th>Home page</th></tr></thead><tbody><tr><td>Owner (and admin)</td><td><strong>Workshop › Dashboard</strong></td></tr><tr><td>Technician</td><td><strong>Workshop › My jobs</strong></td></tr><tr><td>Sales agent</td><td><strong>Sales › My pipeline</strong></td></tr></tbody></table><p><img src="'+a+'" alt="Rakkii Ops sign-in page"></p><div class="info custom-block"><p class="custom-block-title">Practice app only</p><p>The integration (practice) app also shows a <strong>Quick sign-in</strong> box with test accounts and a PIN. The live shop app does not have it.</p></div><div class="warning custom-block"><p class="custom-block-title">&quot;Access needed&quot;?</p><p>Your login has no role yet, or the page is not part of your role. Ask the owner to check your role in <strong>Admin › Staff and pay</strong>.</p></div><h2 id="move-around-hubs-and-menus" tabindex="-1">Move around: hubs and menus <a class="header-anchor" href="#move-around-hubs-and-menus" aria-label="Permalink to &quot;Move around: hubs and menus&quot;">​</a></h2><p>The app is split into <strong>hubs</strong>. Press the hub name in the top bar (for example <strong>Workshop ▾</strong>) to switch. Each hub has its own side menu. On a phone, the menu is behind the ☰ button.</p><table tabindex="0"><thead><tr><th>Hub</th><th>What&#39;s in it</th><th>Who sees it</th></tr></thead><tbody><tr><td><strong>Workshop</strong></td><td>Jobs, shop board, calendar, customers, parts, forms</td><td>Owner, admin, technician (their jobs only)</td></tr><tr><td><strong>Sales</strong></td><td>Pipeline, commission, monitoring, insurance calculator</td><td>Owner, admin, sales</td></tr><tr><td><strong>Finance</strong></td><td>Cash, payments, who owes us, payables, expenses, reports</td><td>Owner, admin</td></tr><tr><td><strong>HR</strong></td><td>Staff directory, attendance, leave, payroll, announcements</td><td>Owner, admin</td></tr><tr><td><strong>Admin</strong></td><td>Shop settings, staff and pay</td><td>Owner</td></tr><tr><td><strong>Me</strong></td><td>Your clock, leave, overtime, payslip, profile</td><td>Everyone</td></tr></tbody></table><p><img src="'+d+'" alt="The hub switcher open"></p><h2 id="find-a-job-fast" tabindex="-1">Find a job fast <a class="header-anchor" href="#find-a-job-fast" aria-label="Permalink to &quot;Find a job fast&quot;">​</a></h2><ul><li>Type a plate, job number or customer name in the search box at the top (<strong>Plate, job or customer</strong>). Press <kbd>/</kbd> to jump to it from anywhere.</li><li>Or open <strong>Workshop › Job history</strong> to filter by date, type (Retail, Insurance, Fleet) and status.</li></ul><p><img src="'+i+'" alt="Top-bar search with results"></p><h2 id="job-page" tabindex="-1">The job page in one minute <a class="header-anchor" href="#job-page" aria-label="Permalink to &quot;The job page in one minute {#job-page}&quot;">​</a></h2><p>Every job opens on the same page. From top to bottom:</p><ol><li><strong>Header</strong>: the plate, the customer and the status (for example <strong>Under repair</strong>).</li><li><strong>Progress card</strong>: seven steps (<strong>Created</strong>, <strong>Booked</strong>, <strong>Work done</strong>, <strong>QC passed</strong>, <strong>Released</strong>, <strong>Paid</strong>, <strong>Done</strong>), a sentence saying what to do now (for example &quot;Add work lines to build the quote.&quot;), and one blue <strong>next-step button</strong> such as <strong>Add work lines →</strong> or <strong>Save quote →</strong>. The button opens the right tab and points at the control. If it&#39;s grey, the reason is written next to it.</li><li><strong>Tabs</strong>: each tab holds one part of the work.</li></ol><table tabindex="0"><thead><tr><th>Tab</th><th>What you do there</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>A summary of the job: customer, car, money, release and the status log</td></tr><tr><td><strong>Canvass</strong></td><td>Supplier prices for parts (only when the job needs it)</td></tr><tr><td><strong>Parts buy</strong></td><td>Buying and receiving parts (only when the job needs it)</td></tr><tr><td><strong>Work</strong></td><td>Work lines, the <strong>Quote</strong>, the team, the bay checklist, QC photos and printing</td></tr><tr><td><strong>Insurance</strong></td><td>Claim, LOA and supplements (insurance jobs only)</td></tr><tr><td><strong>Pay</strong></td><td>What&#39;s owed, invoices and payments</td></tr><tr><td><strong>Files</strong></td><td>Intake checklist, waiver, photos and documents</td></tr><tr><td><strong>Release</strong></td><td>&quot;Can the car leave?&quot; and the release form</td></tr></tbody></table><p>A ✓ on a tab means it&#39;s finished. A ● means it needs you. Technicians see only <strong>Work</strong> and <strong>Files</strong> (plus <strong>Canvass</strong> to view).</p><p><img src="'+e+'" alt="A job page: header, next-step button and tabs"></p><p>Other things to know:</p><ul><li><strong>Hard-to-undo actions ask first.</strong> Saving a quote, posting an invoice, recording a payment and releasing a car each show a confirm box.</li><li><strong>Printing</strong>: on a computer you get the print dialog. On a phone, the paper is saved as a PDF named after the paper and the plate.</li><li><strong>More ▾</strong> in the header holds the less common moves: <strong>Put on hold</strong>, <strong>Cancel job</strong>, <strong>No-show</strong>, and editing the car or customer.</li></ul><h2 id="dark-mode" tabindex="-1">Dark mode <a class="header-anchor" href="#dark-mode" aria-label="Permalink to &quot;Dark mode&quot;">​</a></h2><p>Open your name in the top-right corner and press <strong>Dark mode</strong> (or <strong>Light mode</strong>). The app remembers it on that device.</p><h2 id="words-you-will-see" tabindex="-1">Words you will see <a class="header-anchor" href="#words-you-will-see" aria-label="Permalink to &quot;Words you will see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Job</strong></td><td>One car visit: the customer, car, work, money and paperwork.</td></tr><tr><td><strong>Nature</strong></td><td>Private, Insurance, Corporate, Government or Bidding. It decides the deposit and paperwork rules.</td></tr><tr><td><strong>LOA</strong></td><td>Letter of Authorization from an insurer, with the amount they&#39;ll pay.</td></tr><tr><td><strong>Who pays</strong></td><td>Set on each work line: <strong>Customer</strong> or <strong>Insurer</strong>.</td></tr><tr><td><strong>Target date</strong></td><td>When the repair should be done.</td></tr><tr><td><strong>Appointment</strong></td><td>When the car is booked to come in.</td></tr><tr><td><strong>Released</strong></td><td>The car has left the shop.</td></tr><tr><td><strong>Done</strong></td><td>Nothing is left on the job: work, paperwork and checklist are finished.</td></tr><tr><td><strong>Margin on cost</strong></td><td>(sell − cost) ÷ cost. A ₱300 part sold at ₱800 is 167% on cost.</td></tr><tr><td><strong>Owner override</strong></td><td>The owner lets something through that would normally be blocked. A written reason is always required and saved.</td></tr></tbody></table><p>All dates and times use Manila time.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Technician: <a href="/rakkii-cars-guide/technician/">Your day in the bay</a></li><li>Sales agent: <a href="/rakkii-cars-guide/sales/">Your day in sales</a></li><li>Owner or desk: <a href="/rakkii-cars-guide/desk/">Your day at the desk</a></li></ul>',30)])])}const f=o(h,[["render",g]]);export{y as __pageData,f as default};
